sys_script_include.script:
var FinCrimeConnector = Class.create();
FinCrimeConnector.prototype = {
    initialize: function() {},
    getConnector: function() {
        var property = gs.getProperty('x_vuram_financia_0.fincrime_customer_info_integration');// checking for connector selected
		if (property == 'none') return null;
		switch (property) {
                case 'uk_company_house':
                    return new UKCompanyHouseConnector();

                default:
                    return null;
            }
    },

    type: 'FinCrimeConnector'
};
